import { ProductInformationResponseItem } from "@parksandresorts/webapiproxy-types";
import { StaticConfigContextType, useCurrentContentPageSlugsContext, useStaticConfigContext } from "../contexts";
import { ProductBlockFragment } from "../types";
import { Language } from "../labels/i18n";
import { CurrencyHelper, readonlyMap, isTruthy, throwError } from "../helpers";
import { useMemo } from "react";

// This is the template for what NormalizedProduct should look like. See `NormalizedProduct` for more details.
// These properties are the ones we expect to be shared, but they may be more strict (narrower) in the specific types
// The properties' documentation is inherited from here
type BaseNormalizedProduct = {
  /** GLK product ID */
  productId: number | undefined;
  /**
   * The sales-friendly name of the product
   *
   * Should be used in any context where the user may buy or has bought the product, such as in the webshop, cart, etc.
   */
  name: string;
  /**
   * A display-friendly name of the product for when the user has already bought the product.
   *
   * This is used in My Pages and could differ from the sales-friendly name. For example, for a season pass, the sales-
   * friendly name could be "New-and-improved Season Pass" while the display-friendly name could be just "Season Pass".
   */
  myParksName: string;
  /**
   * A short description of the product, used mainly in the webshop-context.
   */
  description: string | undefined;
  /**
   * A customer-facing string-representation of the price
   *
   * This is not usable for any price calculations, only for displaying to the user. It may include information about
   * discounts, price ranges, or similar.
   */
  price: string | undefined;

  /**
   * The raw GLK product data
   *
   * Used for business logic surrounding price, availability, shipping, and so on.
   */
  glkProduct: ProductInformationResponseItem | undefined;
  /**
   * The raw Contentful product data
   *
   * Used for accessing any editorial content related to the product, such as descriptions, images, and so on.
   */
  contentfulProduct: ProductBlockFragment | undefined;
};

/**
 * A NormalizedProduct when we have a GLK product. The existence of a Contentful product is not guaranteed.
 *
 * NormalizedProduct is the primary way we get data about products in our code-base. The sources for this information is
 * GLK and/or Contentful. Important and frequently used properties are defined in the base object whereas access to the
 * raw GLK/Contentful data can be accessed through their respective properties.
 *
 * Cases where we might have GLK products but no Contentful product include:
 * - Products bought during a visit (in-park purchase), usually via Smart Wristbands
 * - "bonus" or "fake" products, that are added to the cart by the backend, usually as a discount or reward
 * - New products that have not yet been synced to Contentful, but are already purchasable
 */
export type GlkBackedProduct = {
  productId: number;
  name: string;
  myParksName: string;
  description: string | undefined;
  price: string;

  glkProduct: ProductInformationResponseItem;
  contentfulProduct: ProductBlockFragment | undefined;
} & BaseNormalizedProduct;

/**
 * A NormalizedProduct when we only have a Contentful product.
 *
 * NormalizedProduct is the primary way we get data about products in our code-base. The sources for this information is
 * GLK and/or Contentful. Important and frequently used properties are defined in the base object whereas access to the
 * raw GLK/Contentful data can be accessed through their respective properties.
 *
 * Sometimes we want Contentful products without GLK products that are used for purely editorial/presentation purposes:
 * - An "Entry ticket and Ticket-to-Ride"-product which is used in lists to link to a purchase flow
 * - An Event-product which is used in lists to link to a page where the customer can book via external systems
 */
export type ContentfulOnlyProduct = {
  productId: undefined;
  name: string;
  myParksName: string;
  description: string | undefined;
  price: string | undefined;

  glkProduct: undefined;
  contentfulProduct: ProductBlockFragment;
};
// & BaseNormalizedProduct;
// ContentfulOnlyProduct should extend BaseNormalizedProduct so that all docs are consistent, but it does not work
// without strictNullChecks enabled in tsconfig, which we don't have. We should though.

/**
 * NormalizedProduct is the primary way we get data about products in our code-base. The sources for this information is
 * GLK and/or Contentful. Important and frequently used properties are defined in the base object whereas access to the
 * raw GLK/Contentful data can be accessed through their respective properties.
 */
export type NormalizedProduct = GlkBackedProduct | ContentfulOnlyProduct;

type ProductCollection = StaticConfigContextType["products"];

/** Creates a NormalizedProduct. See comments on the types for more information about the properties and differences. */
function normalizeProduct(
  glkProduct: ProductInformationResponseItem | undefined,
  contentfulProduct: ProductBlockFragment | undefined,
  locale: Language,
): NormalizedProduct | undefined {
  if (!glkProduct && !contentfulProduct) {
    return undefined;
  }
  // Typescript does not correctly narrow here, so we disable the rule. This means we need to be particularly careful.
  // What we know is that at least one of glkProduct or contentfulProduct is defined here.
  /* eslint-disable @typescript-eslint/no-non-null-assertion */

  const nameKey =
    locale === "sv" || locale === "nn" // Norwegian should use Swedish, since we do not have explicit Norwegian translations
      ? "Swe"
      : // fallback to English for other locales (including English itself)
        "Eng";
  const name = glkProduct
    ? glkProduct[`friendlySalesName${nameKey}`]
    : contentfulProduct!.productName ||
      throwError("Should not reach here, since either glkProduct or contentfulProduct must be defined");
  const myParksName = glkProduct
    ? glkProduct[`friendlyDisplayName${nameKey}`]
    : contentfulProduct!.productNameMyPages || name;
  const description = contentfulProduct?.shortDescription || undefined;
  const price =
    contentfulProduct?.customPriceText ||
    (glkProduct?.priceIncludingVat
      ? CurrencyHelper.formatToSekWithPossiblePrecision(glkProduct.priceIncludingVat)
      : undefined);

  return glkProduct
    ? ({
        productId: glkProduct.id,
        name,
        myParksName,
        description,
        price: price!,
        glkProduct: glkProduct,
        contentfulProduct: contentfulProduct,
      } satisfies GlkBackedProduct)
    : ({
        productId: undefined,
        name,
        myParksName,
        description,
        price,
        glkProduct: undefined,
        contentfulProduct: contentfulProduct!,
      } satisfies ContentfulOnlyProduct);
}
/* eslint-enable @typescript-eslint/no-non-null-assertion */

/** get the CF product for the current locale, or fallback to the first one (if any) */
function findContentfulProduct(
  contentfulProducts: Array<ProductBlockFragment>,
  locale: Language,
  check: (product: ProductBlockFragment) => boolean,
): ProductBlockFragment | undefined {
  const matchingCfProducts = contentfulProducts.filter(check);
  const correctLocaleProduct = matchingCfProducts.find((product) => product.node_locale === locale);
  return correctLocaleProduct ?? matchingCfProducts[0];
}

function getNormalizedProductByGlkId(glkId: number, products: ProductCollection, locale: Language) {
  const glkProduct = products.glkProducts.find((product) => product.id === glkId);

  const contentfulProduct = findContentfulProduct(
    products.contentfulProducts,
    locale,
    (product) => product.productData?.glkId === glkId.toString(),
  );

  return normalizeProduct(glkProduct, contentfulProduct, locale) as GlkBackedProduct | undefined;
}

function getNormalizedProductByContentfulId(contentfulId: string, products: ProductCollection, locale: Language) {
  const contentfulProduct = findContentfulProduct(
    products.contentfulProducts,
    locale,
    (product) => product.contentful_id === contentfulId,
  );

  const glkId = contentfulProduct?.productData?.glkId ? parseInt(contentfulProduct.productData.glkId, 10) : undefined;
  const glkProduct = glkId ? products.glkProducts.find((product) => product.id === glkId) : undefined;

  return normalizeProduct(glkProduct, contentfulProduct, locale) as
    | (NormalizedProduct & Pick<ContentfulOnlyProduct, "contentfulProduct">)
    | undefined;
}

/** Returns the normalized product (if it exists) for the given GLK ID and current locale */
export function useProduct(glkId: number | undefined) {
  const { currentLocale } = useCurrentContentPageSlugsContext();
  return useProductForLocale(glkId, currentLocale);
}
/** Returns the normalized product (if it exists) for the given GLK ID and locale */
export function useProductForLocale(glkId: number | undefined, locale: Language) {
  const { products } = useStaticConfigContext();

  return useMemo(() => {
    if (!glkId) return undefined;
    return getNormalizedProductByGlkId(glkId, products, locale);
  }, [glkId, locale, products]);
}

/** Returns the normalized product (if it exists) for the given Contentful ID and current locale */
export function useProductByContentfulId(contentfulId: string | undefined) {
  const { currentLocale } = useCurrentContentPageSlugsContext();
  return useProductByContentfulIdForLocale(contentfulId, currentLocale);
}
/** Returns the normalized product (if it exists) for the given Contentful ID and locale */
export function useProductByContentfulIdForLocale(contentfulId: string | undefined, locale: Language) {
  const { products } = useStaticConfigContext();

  return useMemo(() => {
    if (!contentfulId) return undefined;
    return getNormalizedProductByContentfulId(contentfulId, products, locale);
  }, [contentfulId, locale, products]);
}

/**
 * Returns normalized products for the given GLK IDs and current locale.
 *
 * IDs that do not match any product are skipped.
 *
 * @returns `productList`: the (found) products in the same order as the given GLK IDs
 * @returns `productsById`: a record of GLK ID to product for quick lookup when order does not matter
 */
export function useProducts(glkIds: Array<number>) {
  const { currentLocale } = useCurrentContentPageSlugsContext();
  return useProductsForLocale(glkIds, currentLocale);
}
/**
 * Returns normalized products for the given GLK IDs and locale.
 *
 * IDs that do not match any product are skipped.
 *
 * @returns `productList`: the (found) products in the same order as the given GLK IDs
 * @returns `productsById`: a record of GLK ID to product for quick lookup when order does not matter
 */
export function useProductsForLocale(glkIds: Array<number>, locale: Language) {
  const { products } = useStaticConfigContext();

  return useMemo(() => {
    const pairs = glkIds
      .map((glkId) => {
        const p = getNormalizedProductByGlkId(glkId, products, locale);
        return p && ([glkId, p] as const);
      })
      .filter(isTruthy);
    const productsById = readonlyMap(pairs);

    return { productsById, productList: pairs.map(([, product]) => product) };
    // we use glkIds.join(";") to avoid recreating the memoized value when the array reference changes but the content is the same
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [glkIds.join(";"), locale, products]);
}

/**
 * Returns normalized products for the given Contentful IDs and current locale.
 *
 * IDs that do not match any product are skipped.
 *
 * @returns `productList`: the (found) products in the same order as the given Contentful IDs
 * @returns `productsById`: a record of Contentful ID to product for quick lookup when order does not matter
 */
export function useProductsByContentfulIds(contentfulIds: Array<string>) {
  const { currentLocale } = useCurrentContentPageSlugsContext();
  return useProductsByContentfulIdsForLocale(contentfulIds, currentLocale);
}
/**
 * Returns normalized products for the given Contentful IDs and locale.
 *
 * IDs that do not match any product are skipped.
 *
 * @returns `productList`: the (found) products in the same order as the given Contentful IDs
 * @returns `productsById`: a record of Contentful ID to product for quick lookup when order does not matter
 */
export function useProductsByContentfulIdsForLocale(contentfulIds: Array<string>, locale: Language) {
  const { products } = useStaticConfigContext();

  return useMemo(() => {
    const pairs = contentfulIds.map(
      (contentfulId) => [contentfulId, getNormalizedProductByContentfulId(contentfulId, products, locale)] as const,
    );
    const productsById = readonlyMap(pairs);

    return { productsById, productList: pairs.map(([, product]) => product).filter(isTruthy) };
    // we use contentfulIds.join(";") to avoid recreating the memoized value when the array reference changes but the content is the same
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [contentfulIds.join(";"), locale, products]);
}
