import style from "./spoken-text.module.less";

export type SpokenTextProps = {
  text: string;
  ariaLive?: "polite" | "assertive" | "off";
};

/**
 * SpokenText component renders text that is intended to be spoken by a screen reader, to make it more accessible. It is
 * typically paired with a component that has the `aria-hidden` attribute set to true, for which the SpokenText is a
 * substitute.
 *
 * The component can also be matched with an element that is toggled by a button, where the SpokenText provides
 * additional context for screen readers.
 */
export function SpokenText({ text, ariaLive = "off" }: SpokenTextProps) {
  return (
    <>
      <span className={style.spokenText} aria-live={ariaLive} aria-atomic="true">
        {text}
      </span>
    </>
  );
}
