import { useRef } from "react";

export function useOnPreNavigate<TArgs extends Array<unknown> = []>(
  callback?: (evt: React.MouseEvent, ...args: TArgs) => void,
) {
  const targetClickedRef = useRef(false);
  return (event: React.MouseEvent, ...args: TArgs) => {
    if (typeof callback !== "function" || targetClickedRef.current) {
      return;
    }

    targetClickedRef.current = true;

    event.persist();
    event.preventDefault();

    callback(event, ...args);
    (event.target as HTMLAnchorElement).click?.();
  };
}
