import styles from "./cart-item.module.less";
import { RideStore } from "@/core/stores";
import {
  EventAggregator,
  isNonEmptyArray,
  DateHelper,
  createDate,
  CurrencyHelper,
  PlaceholderImageHelper,
  multipleClassNames,
  isTruthy,
} from "@/core/helpers";
import { useTranslation } from "react-i18next";
import Link from "@/core/components/primitives/link/link";
import {
  DeliveryType,
  DynamicData,
  WebshopProductType,
  ResponseQueuePassSlotItem,
  ResponseSlotItem,
} from "@parksandresorts/webapiproxy-types";
import { useOnPreNavigate } from "@/core/hooks/use-on-pre-navigate";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import { forwardRef, useState } from "react";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import Popover from "@/core/components/primitives/popover/popover";
import { useProduct } from "@/core/hooks/product-hooks";
import Icon from "@/core/components/primitives/icon/icon";

const CurrentPrice = ({ item }: { item: ItemInCart }) => {
  if (item.price === undefined) {
    return null;
  }
  return <p className={styles.currentPrice}>{CurrencyHelper.formatToSekWithPossiblePrecision(item.price)}</p>;
};

function getQueuePasses(subItems: Array<SubItemInCart>) {
  const timeSlots = subItems.filter(
    (item): item is typeof item & { slot: ResponseQueuePassSlotItem } =>
      item.slot?.SlotType === "QueuePass" || item.slot?.SlotType === "JetshopTimeSlot",
  );
  const extendedTimeSlots = timeSlots.map(({ slot }) => {
    const ride = RideStore.getRideById(slot.locationId);
    return {
      ...slot,
      rideName: ride ? ride.title : "",
    };
  });

  const sortedTimeSlots = [...extendedTimeSlots].sort((a, b) => {
    if (!(a.slotFrom && b.slotFrom)) {
      return 0;
    }

    return createDate(a.slotFrom).valueOf() - createDate(b.slotFrom).valueOf();
  });

  return sortedTimeSlots;
}

export type SubItemInCart = {
  name: string;
  slot: Pick<ResponseSlotItem, "SlotType" | "isFullDay" | "slotFrom"> | undefined;
};

export type ItemInCart = {
  id: string;
  productId: number | null;
  name: string;
  price?: number;
  unitPriceIncludingVat: number;
  quantity: number;
  minimumQuantity: number;
  stockQuantity?: number;
  previousTotalPrice?: number;
  metadata?: Array<string>;
  visitorName: string | undefined;
  subItems: Array<SubItemInCart>;
  redeemableItems?: Array<
    | { type: "voucher"; id: string; code: string; amount: number }
    | { type: "promotionTier"; id: string; campaignName: string; amount: number }
  >;
  data: DynamicData | undefined;
  deliveryType: DeliveryType;
  productType: WebshopProductType;
};

export type CartItemProps = {
  item: ItemInCart;
  isDisabled: boolean;
  deleteCartItem?: (cartItem: ItemInCart, announcement?: string) => void;
  updateCartItemQuantity?: (cartItem: ItemInCart, newQuantity: number) => void;
};

const CartItem = forwardRef<HTMLDivElement, CartItemProps>(
  ({ item, isDisabled, deleteCartItem, updateCartItemQuantity }, ref) => {
    const { t } = useTranslation();
    const [liveMessage, setLiveMessage] = useState<string | null>(null);
    const [quantitySelectorOpen, setQuantitySelectorOpen] = useState(false);

    const minimumQuantity = item.minimumQuantity;

    const productType = item.productType;
    const product = useProduct(item.productId ?? undefined);

    const productName = item.name;
    const productImageUrl =
      product?.contentfulProduct?.productImage?.file?.url ?? PlaceholderImageHelper.getPlaceholderImage("cartItem");
    const productUrl = product?.contentfulProduct?.productPageLink?.slug;

    const isShippingProduct = productType === WebshopProductType.SHIPPING_FEE;

    // The only kind of subItems we handle right now are queue passes and time passes
    const queuePasses = getQueuePasses(item.subItems);
    const timePasses = item.subItems.filter((item) => item.slot?.SlotType === "TimePass");

    function isQuantityIncreaseDisabled() {
      switch (productType) {
        // New ShopService types
        case WebshopProductType.BOOKABLE_TIMESLOT:
        case WebshopProductType.CARD_REACTIVATION: // I assume this should be handled like "ReloadCardWithCardHolder"
          return true;
        // these are not defined in the enum but we keep them for backward compatibility
        case "ActivityPass" as WebshopProductType:
        case "QueuePass" as WebshopProductType:
        case "TimePass" as WebshopProductType:
        case "DatePass" as WebshopProductType: // Maybe this should be handled differently?
          return true;
      }
      if (item.quantity >= (item.stockQuantity ?? Number.MAX_SAFE_INTEGER)) {
        return true;
      }

      if (item.data && Object.keys(item.data).length > 0) {
        return true;
      }

      return false;
    }

    const handleQuantityChange = (quantity: number) => {
      if (!updateCartItemQuantity || !deleteCartItem) {
        return;
      }

      const incOrDecQuantity = quantity - item.quantity;
      let actionMsg = "";

      if (incOrDecQuantity === -1 && (item.quantity === 1 || item.quantity === minimumQuantity)) {
        actionMsg = t("cartItemRemoved", { name: productName });

        EventAggregator.publish("trackEvent", {
          category: "Cart",
          action: "Deleted item",
          label: productName,
        });
        deleteCartItem(item, actionMsg);
        return;
      } else {
        updateCartItemQuantity(item, item.quantity + incOrDecQuantity);
        actionMsg = t("cartItemUpdated", {
          name: productName,
          quantity: item.quantity + incOrDecQuantity,
          price: CurrencyHelper.formatToSekWithPossiblePrecision(
            (item.price ?? 0) + incOrDecQuantity * item.unitPriceIncludingVat,
          ),
        });
        setLiveMessage(actionMsg);
        EventAggregator.publish("trackEvent", {
          category: "Cart",
          action: incOrDecQuantity < 0 ? "Decrease item" : "Increase item",
          label: productName,
        });
      }
    };

    // Compose a single accessibility label for the item
    const accessibilityLabel = [
      productName,
      isNonEmptyArray(item.metadata) && `(${item.metadata.join(", ")})`,
      t("cartItemQuantity", { count: item.quantity }),
      typeof item.previousTotalPrice === "number" &&
        t("cartItemPreviousTotal", { price: CurrencyHelper.formatToSekWithPossiblePrecision(item.previousTotalPrice) }),
      isNonEmptyArray(item.redeemableItems?.filter((r) => r.type === "voucher"))
        ? `${t("usedVoucherCodes")}: ${item.redeemableItems
            ?.map(
              (r) => r.type === "voucher" && `${r.code} ${CurrencyHelper.formatToSekWithPossiblePrecision(r.amount)}`,
            )
            .filter(isTruthy)
            .join(", ")}`
        : null,
      t("cartItemTotal", { price: CurrencyHelper.formatToSekWithPossiblePrecision(item.price ?? 0) }),
      isNonEmptyArray(queuePasses) &&
        queuePasses
          .map((slot) => `${DateHelper.toStringTimeHHMM(slot.slotFrom)}${slot.rideName ? ` - ${slot.rideName}` : ""}`)
          .join(", "),
      isNonEmptyArray(timePasses) &&
        timePasses
          .map(
            (slot) =>
              `${slot.name}: ${DateHelper.toStringTimeHHMM(slot.slot?.slotFrom)}${
                slot.slot?.isFullDay ? t("cartItemFullDayTimePass") : ""
              }`,
          )
          .join(", "),
    ]
      .filter(Boolean)
      .join(". ");

    const metadataRows = [
      item.quantity > 1 ? `${CurrencyHelper.formatToSekWithPossiblePrecision(item.unitPriceIncludingVat)} / st` : null,
      ...(item.metadata ?? []),
    ].filter(isTruthy);

    const onClickLink = useOnPreNavigate(() =>
      EventAggregator.publish("trackEvent", {
        category: "Cart",
        action: "Clicked link",
        label: productName,
      }),
    );

    return (
      <div className={styles.cartItem} tabIndex={-1} aria-label={accessibilityLabel} ref={ref} data-testid="cart-item">
        <SpokenText text={liveMessage || ""} ariaLive="assertive" />
        {/* Header: [Image] [title, product info] [price(s), quantity]*/}
        <div className={styles.header}>
          {productImageUrl && !isShippingProduct && (
            <Link internalLink={productUrl} onClick={onClickLink} className={styles.imageLink}>
              <div
                className={styles.image}
                style={{
                  backgroundImage: `url(${productImageUrl})`,
                }}
              />
              <div className={styles.imageGradient}> </div>
            </Link>
          )}
          <Link
            className={multipleClassNames(styles.titleAndInfo, styles.link)}
            internalLink={productUrl}
            onClick={onClickLink}
          >
            <div
              className={styles.titleAndInfo}
              data-image-is-rendered={!!productImageUrl && !isShippingProduct}
              data-has-link={!!productUrl}
            >
              <p className="bold">{productName}</p>
              {isNonEmptyArray(metadataRows) && (
                <>
                  {metadataRows.map((meta, index) => (
                    <p key={index} className="body-xs">
                      {meta}
                    </p>
                  ))}
                </>
              )}
              {isNonEmptyArray(timePasses) && (
                <>
                  {timePasses.map((slot, index) => (
                    <p key={index} className="body-xs">
                      <span className="bold">{slot.name}</span>
                      {`: ${DateHelper.toStringTimeHHMM(slot.slot?.slotFrom)}${
                        slot.slot?.isFullDay ? t("cartItemFullDayTimePass") : ""
                      }`}
                    </p>
                  ))}
                </>
              )}
            </div>
          </Link>
          <div className={styles.priceAndQuantity}>
            <div className={styles.prices}>
              {typeof item.previousTotalPrice === "number" && (
                <s className={styles.previousPrice}>
                  {CurrencyHelper.formatToSekWithPossiblePrecision(item.previousTotalPrice)}
                </s>
              )}

              {/* When we have redeemable items, show the total price at the bottom instead */}
              {!isNonEmptyArray(item.redeemableItems) && <CurrentPrice item={item} />}
            </div>
            {!isShippingProduct && (item.price ?? 0) >= 0 && !!deleteCartItem && !!updateCartItemQuantity && (
              <Popover
                asModal
                contentClassName={styles.quantityPopoverContent}
                isOpenOverride={quantitySelectorOpen}
                setIsOpenOverride={setQuantitySelectorOpen}
                triggerButton={{
                  buttonType: "OutlineButton",
                  label: item.quantity.toString(),
                  ariaLabel: t("cartItemQuantityTriggerLabel", { count: item.quantity }),
                  iconRightNew: quantitySelectorOpen ? "expand-less" : "expand-more",
                }}
              >
                <p className="bold">{t("cartItemQuantitySelector")}</p>
                <div>
                  <QuantitySelectorStyled
                    isDisabled={isDisabled}
                    quantity={item.quantity}
                    maxQuantity={isQuantityIncreaseDisabled() ? item.quantity : item.stockQuantity}
                    onQuantityChange={handleQuantityChange}
                    removeQuantityIconOverride="trash"
                  />
                </div>
              </Popover>
            )}
            {!isShippingProduct && (!deleteCartItem || !updateCartItemQuantity) && item.quantity !== 1 && (
              <p className="bold">{t("pieces", { count: item.quantity })}</p>
            )}
          </div>
        </div>
        {/* Subitems: Queuepasses*/}
        {isNonEmptyArray(queuePasses) && (
          <div className={styles.expressPassWrapper}>
            <hr className={styles.expressPassDivider} />
            <p className="bold body-xs" data-contentful-label-id="cartQueuePassesHeading">
              {t("cartQueuePassesHeading")}
            </p>
            <ul className={styles.expressPassList}>
              {queuePasses.map((timeSlot) => (
                <li key={timeSlot.slotId} className="body-xs">
                  {DateHelper.toStringTimeHHMM(timeSlot.slotFrom)}
                  {timeSlot.rideName ? ` - ${timeSlot.rideName}` : ""}
                </li>
              ))}
            </ul>
          </div>
        )}
        {/* Redeemables (Voucher codes and promotion tiers) */}
        {isNonEmptyArray(item.redeemableItems) && (
          <div className={styles.redeemableWrapper}>
            <hr className={styles.redeemableDivider} />
            <ul className={styles.redeemableList}>
              {item.redeemableItems.map((redeemable) => (
                <li key={redeemable.id} className="body-s">
                  <div className={styles.redeemableCode}>
                    <Icon name="discount" />
                    <p>{redeemable.type === "voucher" ? redeemable.code : redeemable.campaignName}</p>
                  </div>
                  <p>{CurrencyHelper.formatToSekWithPossiblePrecision(redeemable.amount)}</p>
                </li>
              ))}
            </ul>
            <CurrentPrice item={item} />
          </div>
        )}
      </div>
    );
  },
);

CartItem.displayName = "CartItem";

export default CartItem;
